# `ready` arriving means the table exists; the form's two values become
# the insert's parameter list. An empty credits field enrolls with 5.
return {"params": [telegramId, credits or "5"]}

# The query takes its parameters as a list; the sender's id arrives as
# one string. Wrap it.
return {"params": [user]}

# The query returns one row: user_id when the credit was taken, refusal
# when it was not. Returning no "refusal" key closes that port, which is
# what skips the apology message downstream.
row = rows[0]
if row.get("refusal"):
    return {"paid": False, "refusal": row["refusal"]}
return {"paid": True}
